trigger_evidence:
Alert.alert(
        "Lookup created",
        "The lookup was created as a draft. Add options, then publish it when ready.",
        [
          {
            text: "Open Lookup",
            onPress: () =>
              router.replace({
                pathname: "/(tabs)/admin/settings/select-lookups/[lookupKey]",
                params: {
                  lookupKey: nextLookupKey,
                },
              }),
          },
        ],
      )

Alert.alert("Option updated", "The option was saved.", [
          {
            text: "OK",
            onPress: () =>
              router.replace({
                pathname: "/(tabs)/admin/settings/select-lookups/[lookupKey]",
                params: { lookupKey },
              }),
          },
        ])

Alert.alert(
        "Option created",
        "The option was created as DRAFT. Publish it from the lookup detail screen when ready.",
        [
          {
            text: "OK",
            onPress: () =>
              router.replace({
                pathname: "/(tabs)/admin/settings/select-lookups/[lookupKey]",
                params: { lookupKey },
              }),
          },
        ],
      )

Alert.alert(title || label, message || "Are you sure?", [
      {
        text: "Cancel",
        style: "cancel",
      },
      {
        text: label,
        style: color === "#B91C1C" ? "destructive" : "default",
        onPress: onConfirm,
      },
    ])

Alert.alert(
                "Archive option",
                `Archive option ${optionCode}? System options cannot be archived.`,
                [
                  {
                    text: "Cancel",
                    style: "cancel",
                  },
                  {
                    text: "Archive",
                    style: "destructive",
                    onPress: () =>
                      onSetStatus({
                        optionCode,
                        action: "ARCHIVE_OPTION",
                      }),
                  },
                ],
              )

{
      action,
      uid: actor.uid,
      message: error?.message || String(error),
      code: error?.code || "unknown",
    }
